import { X509Certificate, KeyObject, createPrivateKey } from "node:crypto";
import { readFileSync } from "node:fs";
import { strict as assert } from "node:assert";

const cert = new X509Certificate(readFileSync(import.meta.dir + "/agent1-cert.pem"));
const issuer = new X509Certificate(readFileSync(import.meta.dir + "/ca1-cert.pem"));
const unrelated = new X509Certificate(readFileSync(import.meta.dir + "/ca2-cert.pem"));
assert.equal(cert.subject, "C=US\nST=CA\nL=SF\nO=Joyent\nOU=Node.js\nCN=agent1\nemailAddress=ry@tinyclouds.org");
assert.equal(cert.validFrom, "Sep  3 21:40:37 2022 GMT");
assert.equal(cert.validTo, "Jun 17 21:40:37 2296 GMT");
assert.equal(cert.validFromDate.toISOString(), "2022-09-03T21:40:37.000Z");
assert.equal(cert.validToDate.toISOString(), "2296-06-17T21:40:37.000Z");
assert.equal(cert.serialNumber, "147D36C1C2F74206DE9FAB5F2226D78ADB00A426");
assert.equal(cert.fingerprint, "8B:89:16:C4:99:87:D2:13:1A:64:94:36:38:A5:32:01:F0:95:3B:53");
assert.equal(cert.fingerprint256, "2C:62:59:16:91:89:AB:90:6A:3E:98:88:A6:D3:C5:58:58:6C:AE:FF:9C:33:22:7C:B6:77:D3:34:E7:53:4B:05");
assert.equal(cert.fingerprint512.split(":").length, 64);
assert.equal(cert.signatureAlgorithm, "sha256WithRSAEncryption");
assert.equal(cert.signatureAlgorithmOid, "1.2.840.113549.1.1.11");
assert.equal(cert.ca, false);
assert.equal(issuer.ca, true);
assert.equal(cert.subjectAltName, undefined);
assert.equal(cert.infoAccess, "OCSP - URI:http://ocsp.nodejs.org/\nCA Issuers - URI:http://ca.nodejs.org/ca.cert\n");
assert.equal(cert.toString(), cert.toJSON());
assert.equal(new X509Certificate(cert.raw).toString(), cert.toString());
assert.equal(new X509Certificate(cert.toString().replaceAll("\n", "\r\n")).fingerprint, cert.fingerprint);
assert.throws(() => new X509Certificate("invalid"));
assert.throws(() => new X509Certificate(123), { code: "ERR_INVALID_ARG_TYPE" });
console.log("PEM, DER, names, dates, and fingerprints pass");

assert.equal(cert.publicKey instanceof KeyObject, true);
assert.equal(cert.publicKey.type, "public");
assert.equal(cert.publicKey, cert.publicKey);
assert.equal(cert.checkIssued(issuer), true);
assert.equal(cert.checkIssued(unrelated), false);
assert.equal(cert.checkIssued(cert), false);
assert.equal(issuer.checkIssued(issuer), true);
assert.equal(cert.verify(issuer.publicKey), true);
assert.equal(cert.verify(cert.publicKey), false);
assert.equal(cert.checkPrivateKey(createPrivateKey(readFileSync(import.meta.dir + "/agent1-key.pem"))), true);
assert.throws(() => cert.verify({}), { code: "ERR_INVALID_ARG_TYPE" });
assert.throws(() => cert.checkIssued({}), { code: "ERR_INVALID_ARG_TYPE" });
assert.equal(cert.checkHost("AGENT1"), "agent1");
assert.equal(cert.checkHost("agent1", { subject: "never" }), undefined);
assert.equal(cert.checkHost("agent2"), undefined);
assert.equal(cert.checkEmail("ry@TINYCLOUDS.ORG"), "ry@TINYCLOUDS.ORG");
assert.equal(cert.checkEmail("unrelated@example.com"), undefined);
assert.equal(cert.checkIP("127.0.0.1"), undefined);
assert.throws(() => cert.checkHost("agent\0"), { code: "ERR_INVALID_ARG_VALUE" });
assert.throws(() => cert.checkIP("[::]"), { code: "ERR_INVALID_ARG_VALUE" });
assert.throws(() => cert.checkHost("agent1", { wildcards: 1 }), { code: "ERR_INVALID_ARG_TYPE" });
console.log("KeyObject, signature, issuer, and name checks pass");

const legacy = cert.toLegacyObject();
assert.equal(legacy.subject.CN, "agent1");
assert.equal(legacy.issuer.CN, "ca1");
assert.equal(legacy.serialNumber, cert.serialNumber);
assert.equal(legacy.modulus.startsWith("D456320AFB20D3827093DC2C4284ED04DFBABD56"), true);
assert.equal(legacy.exponent, "0x10001");
assert.equal(legacy.bits, 2048);
assert.equal(legacy.fingerprint256, cert.fingerprint256);
assert.equal(legacy.raw.equals(cert.raw), true);
class Certificate extends X509Certificate {}
assert.equal(new Certificate(cert.raw) instanceof Certificate, true);
console.log("legacy fields and subclassing pass");
const escaped = new X509Certificate(readFileSync(import.meta.dir + "/escaped-san.pem"));
assert.equal(escaped.subjectAltName, 'DNS:"good.example.com\\u002c DNS:evil.example.com"');
assert.equal(escaped.toLegacyObject().subjectaltname, escaped.subjectAltName);
console.log("alternative name escaping passes");
const unknownAccess = new X509Certificate(readFileSync(import.meta.dir + "/unknown-access.pem"));
assert.equal(unknownAccess.infoAccess, "1.3.9999.12.34 - URI:http://ca.example.com/\n");
assert.deepEqual(unknownAccess.toLegacyObject().infoAccess["1.3.9999.12.34 - URI"], ["http://ca.example.com/"]);
console.log("unknown access method OIDs pass");
